#include <stdio.h>
#include <stdlib.h>

int *copy_positives(const int *values, int length, int *out_length) {
    int *result = malloc((size_t)length * sizeof(int));
    if (result == NULL) {
        *out_length = 0;
        return NULL;
    }
    int count = 0;
    for (int index = 0; index < length; index += 1) {
        if (values[index] > 0) {
            result[count] = values[index];
            count += 1;
        }
    }
    *out_length = count;
    return result;
}

int main(void) {
    int values[] = { 3, -1, 2, 7 };
    int count = 0;
    int *positives = copy_positives(values, 4, &count);
    if (positives != NULL) {
        for (int index = 0; index < count; index += 1) {
            printf("%d\n", positives[index]);
        }
        free(positives);
    }
    return 0;
}
